"use strict";
// Question 1 — Variables & Data Types
// Type: Basic
// Description:
// Ek student ki information store karne ke liye variables banao:
// - Student name
// - Student age
// - Is student enrolled?
// - Student marks
// Expected Output:
// Name: Ahsan
// Age: 23
// Enrolled: true
// Marks: 85
// Task: TypeScript mein appropriate data types ke saath variables declare karo aur output print karo.
let studentName = "Syed Ahsan Kazmi";
let studentAge = 23;
let isEnrolled = true;
let marks = 85;
console.log("Name:", studentName);
console.log("Age:", studentAge);
console.log("Enrolled:", isEnrolled);
console.log("Marks:", marks);
